#include <memory>
#include <cassert>
#include <type_traits>
#include <utility>
// Raw pointers use std::to_address; custom pointer traits can supply to_address.
struct Pointer {
    using element_type = int;
    int *value;
    int *operator->() const { return value; }
};
int main() {
    int value = 42;
    auto *pointer = std::pointer_traits<int *>::pointer_to(value);
    assert(std::to_address(pointer) == &value);
}
